mapper.select:
SELECT `character`.*, `creation_record`.action_timestamp as creation_timestamp, `modification_record`.action_timestamp as modification_timestamp, `creation_record`.user_name as creator, `creation_record`.role_name, `creation_record`.role_id, `ctg`.`position` as group_position, `group`.name as group_name, FROM `character` JOIN `action_lineage` as creation_record on creation_record.id = `character`.creation_record_id JOIN `action_lineage` as modification_record on modification_record.id = `character`.modification_record_id LEFT JOIN `character_type` on `character`.`id` = `character_type`.`character_id` LEFT JOIN `haki` on `character`.id = haki.character_id LEFT JOIN `character_to_fruit` on `character`.id = character_to_fruit.character_id LEFT JOIN `character_to_group` as ctg on (`character`.id = `ctg`.`character_id` AND `ctg`.`once_belonged_to` = FALSE) LEFT JOIN `group` on `ctg`.group_id = `group`.id WHERE ( `character`.user_id = #{userId}
OR `character`.id IN
#{externalResourceId}
)
GROUP BY `character`.`id` ORDER BY
LIMIT #{offset}, #{size}

select count(distinct(`character`.id)) FROM `character` LEFT JOIN `character_type` on `character`.`id` = `character_type`.`character_id` LEFT JOIN `haki` on `character`.id = haki.`character_id` LEFT JOIN `character_to_fruit` on `character`.id = character_to_fruit.character_id WHERE ( user_id = #{userId}
OR `character`.id IN
#{externalResourceId}
)
